import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const h=JSON.parse('{"title":"محرك الصلاحيات ونطاق البيانات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/permissions/README.md","filePath":"ar/permissions/README.md"}'),a={name:"ar/permissions/README.md"};function c(i,t,n,s,p,l){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="محرك-الصلاحيات-ونطاق-البيانات" tabindex="-1">محرك الصلاحيات ونطاق البيانات <a class="header-anchor" href="#محرك-الصلاحيات-ونطاق-البيانات" aria-label="Permalink to &quot;محرك الصلاحيات ونطاق البيانات&quot;">​</a></h1><p>نظام تحكم في الوصول بمحركين: محرك يقرر أنهي <strong>شاشات/أفعال</strong> يقدر المستخدم يوصلها (الصلاحيات الوظيفية)، ومحرك تاني مستقل تمامًا يقرر أنهي <strong>صفوف بيانات</strong> يقدر نفس المستخدم يشوفها بمجرد دخوله الشاشة (نطاق البيانات). كل ميزة موثّقة هنا متنفذة وعليها اختبارات Pest إلا لو اتكتب صراحة 🔮 مخطط لها أو ❌ غير مدعومة — راجع <a href="./testing">testing.md</a> لمعرفة الموثّق فعليًا.</p><h2 id="ليه-محركين-مش-محرك-واحد" tabindex="-1">ليه محركين مش محرك واحد <a class="header-anchor" href="#ليه-محركين-مش-محرك-واحد" aria-label="Permalink to &quot;ليه محركين مش محرك واحد&quot;">​</a></h2><p>فحص صلاحية واحد بيجاوب &quot;المستخدم ده يقدر يشوف الفواتير؟&quot; مش هيقدر يجاوب كمان &quot;فواتير أنهي شركة؟&quot; — دمج السؤالين في آلية واحدة هو أشهر سبب لانهيار التحكم في الوصول في أي ERP (باج في النطاق بيبان كأنه باج في الصلاحية والعكس، وإصلاح واحد بيكسر التاني بصمت). النظام ده بيفصلهم بنيويًا:</p><table tabindex="0"><thead><tr><th>السؤال</th><th>الآلية</th><th>الكلاس الأساسي</th></tr></thead><tbody><tr><td>أنهي شاشات/أفعال يقدر يفتحها؟</td><td>أدوار/صلاحيات Spatie، بتتزامن تلقائيًا من الهيكل التنظيمي</td><td><code>App\\Support\\Organization\\EmployeePermissionSynchronizer</code></td></tr><tr><td>أنهي صفوف بيانات يشوفها؟</td><td>مجموعة IDs محسوبة ومُخزّنة (entity/branch/department)</td><td><code>App\\Support\\Organization\\OrganizationScopeResolver</code></td></tr></tbody></table><p>الفحصين بيتطبقوا على كل طلب، بشكل مستقل. مدير مبيعات ممكن يكون عنده رؤية بيانات كاملة على الشركة كلها وبرضه يرجّع <code>can(&#39;fin-gl-jou.view&#39;) === false</code> — رتبته في الهيكل التنظيمي مالهاش علاقة بالصلاحيات الوظيفية، ومنحة وظيفية واسعة مالهاش علاقة بأنهي صفوف هترجع من أي استعلام.</p><h2 id="اللي-هو-فعليًا" tabindex="-1">اللي هو فعليًا <a class="header-anchor" href="#اللي-هو-فعليًا" aria-label="Permalink to &quot;اللي هو فعليًا&quot;">​</a></h2><ul><li><strong>الهيكل التنظيمي</strong> (<code>Modules/HR/Models/OrganizationStructure/</code>) — <code>Entity</code>, <code>Branch</code>, <code>Department</code> (كتالوج عام، مش صف لكل شركة — شوف <a href="./data-scope#departments-are-a-shared-catalog">data-scope.md</a>), <code>JobTitle</code>, <code>JobGrade</code>. <code>Entity</code>/<code>Department</code> بيستخدموا عمود <code>path</code> (materialized path) لاستعلامات الفروع التابعة.</li><li><strong>السجل المحوري</strong> — <code>Modules\\HR\\Models\\EmployeeManagement\\Employee</code> هو الجسر الوحيد بين <code>User</code> مسجّل دخول والهيكل التنظيمي. شوف <a href="./data-scope">data-scope.md</a>.</li><li><strong>محرك نطاق البيانات</strong> (<code>app/Support/Organization/</code>) — <code>OrganizationScopeResolver</code>, <code>OrganizationScope</code> (كائن النتيجة)، <code>OrganizationVersion</code> (إبطال الكاش)، <code>OrganizationScopeConstraint</code> (الـ Eloquent global scope)، و trait <code>App\\Models\\Concerns\\ScopedToOrganization</code> اللي أي موديل يستخدمها.</li><li><strong>محرك الصلاحيات الوظيفية</strong> — <code>php artisan permissions:sync</code> بيولّد كل صلاحيات Spatie من أكواد <code>modules</code>/<code>sub_modules</code>/<code>applications</code> الموجودة أصلاً؛ <code>department_permissions</code> / <code>job_title_permissions</code> / <code>job_title_grade_permissions</code> / <code>job_title_grade_roles</code> هي جداول المنح؛ <code>EmployeePermissionSynchronizer</code> هو الكاتب الوحيد لـ <code>model_has_permissions</code>/<code>model_has_roles</code>؛ <code>php artisan hr:permissions:reconcile</code> هو حارس الانحراف.</li></ul><h2 id="جدول-الميزات" tabindex="-1">جدول الميزات <a class="header-anchor" href="#جدول-الميزات" aria-label="Permalink to &quot;جدول الميزات&quot;">​</a></h2><table tabindex="0"><thead><tr><th>الميزة</th><th>الحالة</th></tr></thead><tbody><tr><td>هيكل تنظيمي (Entity/Branch/Department/JobTitle/JobGrade) بشجرة materialized-path</td><td>✅ متنفذ</td></tr><tr><td>إدارات كتالوج عام مشترك بين الشركات (pivot <code>department_entity</code>)</td><td>✅ متنفذ</td></tr><tr><td><code>Employee</code> كجسر وحيد بين User والهيكل التنظيمي</td><td>✅ متنفذ</td></tr><tr><td>نطاق بيانات بُعدين (<code>entity_scope</code> × <code>department_scope</code>، كتقاطع)</td><td>✅ متنفذ</td></tr><tr><td>تخزين مؤقت لنتيجة النطاق مع إبطال بعدّاد واحد (<code>OrganizationVersion</code>)</td><td>✅ متنفذ</td></tr><tr><td>trait <code>ScopedToOrganization</code> — تفعيل اختياري لأي موديل في أي موديول</td><td>✅ متنفذ</td></tr><tr><td>رفض كامل عند عدم وجود مستخدم مسجّل / موظف نشط</td><td>✅ متنفذ</td></tr><tr><td>رفض آمن (مش انهيار) عند حذف كيان/إدارة بالحذف الناعم أثناء الشجرة</td><td>✅ متنفذ</td></tr><tr><td>تخطي <code>super_admin</code> للمحركين الاتنين بشكل مستقل</td><td>✅ متنفذ</td></tr><tr><td>توليد الصلاحيات تلقائيًا من أكواد الهيكل الملاحي</td><td>✅ متنفذ — <code>permissions:sync</code></td></tr><tr><td>جداول منح: قطاع / لقب وظيفي / لقب+درجة فما فوق / أدوار مسمّاة</td><td>✅ متنفذ</td></tr><tr><td>مزامنة Spatie تلقائية عند التعيين/النقل/الترقية/إنهاء الخدمة</td><td>✅ متنفذ</td></tr><tr><td>كشف وتصحيح الانحراف (<code>hr:permissions:reconcile</code>، بخيار <code>--dry-run</code>)</td><td>✅ متنفذ</td></tr><tr><td>فلترة شجرة التنقّل (القائمة الجانبية) بالصلاحية على الثلاث مستويات</td><td>✅ متنفذ</td></tr><tr><td>صلاحيات على مستوى الحقل (زي إخفاء عمود مالي عن ألقاب معينة)</td><td>✅ متنفذ — عن طريق <code>Column::visible()</code> / callbacks الحقول الموجودة أصلاً، بلا آلية جديدة</td></tr><tr><td>نطاق &quot;سجلاته هو بس&quot; (Employee Self Service) كقيمة نطاق مستقلة</td><td>✅ متنفذ (القيمة بس — شاشات submodule الخدمة الذاتية لسه ما اتبنتش)</td></tr><tr><td>مدير إدارة بيرث تلقائيًا نطاق على الإدارات الفرعية</td><td>✅ متنفذ — <code>department_scope = department_tree</code></td></tr><tr><td>منح نطاق لمدير إقليمي/متعدد الفروع بعيد عن <code>entity_scope</code> القياسي</td><td>🔮 مخطط له — <code>hr_employee_scope_grants</code> (جدول منح إضافي)</td></tr><tr><td>سجل تاريخي لتغيّر الوظيفة/الراتب عبر الوقت</td><td>🔮 مخطط له — <code>employee_assignment_history</code></td></tr><tr><td>دورات اعتماد مستندية (خطوات متعددة، استثناءات)</td><td>🔮 مخطط له — محرك منفصل، مؤجّل عمدًا</td></tr><tr><td>شاشات تعديل (Edit) لسجلات الهيكل التنظيمي</td><td>❌ غير متنفذ — محرك <code>DynamicForm</code> إنشاء فقط في هذه المرحلة</td></tr><tr><td>واجهة لإدارة ربط <code>department_entity</code> / <code>job_title_grade</code></td><td>❌ غير متنفذ — الربط عن طريق <code>Department::attachToEntity()</code> / <code>JobTitle::jobGrades()-&gt;attach()</code> مباشرة؛ تبويبات &quot;الشركات&quot;/&quot;الدرجات&quot; في صفحة العرض للقراءة فقط</td></tr></tbody></table><p>الجدول ده لازم يفضل صادق — حدّثه لما حالة صف تتغيّر فعليًا، مش بس لما ميزة تتشحن.</p><h2 id="التثبيت" tabindex="-1">التثبيت <a class="header-anchor" href="#التثبيت" aria-label="Permalink to &quot;التثبيت&quot;">​</a></h2><p>مفيش حاجة تتثبّت. مبني كامل على حزم موجودة أصلاً: Laravel 13، <code>spatie/laravel-permission</code> 8.3 (كانت مثبّتة وغير مستخدمة قبل المحرك ده)، Livewire 4، Pest 5. مفيش أي حزمة Composer جديدة اتضافت.</p><h2 id="فين-تكمل" tabindex="-1">فين تكمل <a class="header-anchor" href="#فين-تكمل" aria-label="Permalink to &quot;فين تكمل&quot;">​</a></h2><ul><li><a href="./data-scope">data-scope.md</a> — الهيكل التنظيمي، سجل <code>Employee</code>، <code>entity_scope</code> / <code>department_scope</code>، الكاش والإبطال، trait <code>ScopedToOrganization</code>.</li><li><a href="./functional-permissions">functional-permissions.md</a> — توليد الصلاحيات، جداول المنح، المزامنة، تصحيح الانحراف.</li><li><a href="./testing">testing.md</a> — مصفوفة السيناريوهات كاملة وفين كل واحد منها مُثبت.</li><li>المستخدمين: <a href="./../user-guide/permissions">../user-guide/permissions.md</a> — منح/سحب صلاحية موظف، بكلام عادي بلا كود.</li></ul>',15)])])}const u=e(a,[["render",c]]);export{h as __pageData,u as default};
